  "city.doppel-parlor.description": "Ruang tamu di sisi Lab Riset Pusat Doppel. Tamu dipersilakan duduk dan diberi jurnal riset halaman demi halaman.",
  "city.doppel-lab.description": "Lembaga riset dalam yang terletak jauh di dalam lab riset Doppel. Buku harian para peneliti yang pernah dikirim ke Eternal terkumpul di sini.",
  "city.doppel-lab.displayName": "Doppel · Lembaga Riset Dalam",
  "city.doppel-office.description": "Bagian administrasi Doppel yang merekap hasil riset dan penggunaan relik. Persetujuan melewati banyak tingkat, jadi harus menunggu lama.",
  "city.doppel-office.displayName": "Doppel · Bagian Administrasi",
  "city.rust-garage.description": "Bengkel perawatan Rust. Permintaan memperbaiki peralatan riset yang rusak datang tanpa henti.",
  "city.rust-garage.displayName": "Rust · Bengkel Perawatan",
  "city.rust-lease.description": "Bagian manajemen sewa Rust yang menyewakan peralatan berkinerja tinggi. Satu perpanjangan saja bisa memicu negosiasi panjang.",
  "city.rust-lease.displayName": "Rust · Manajemen Sewa",
  "city.doppel-upper.description": "Lantai tertinggi lab riset Doppel. Orang-orang yang menentukan tujuan riset duduk di sini.",
  "city.doppel-upper.displayName": "Doppel · Jajaran Atas",
  "city.rust-works.description": "Pengecoran raksasa di jantung Rust. Perancangan dan perbaikan peralatan riset semuanya berkumpul di satu tempat.",
  "city.rust-works.displayName": "Rust · Pengecoran Pusat",
  "city.odidi-embassy.description": "Ruang penerimaan tempat Odidi, kota peneliti mimpi, menyambut tamu dari luar. Usulan selalu mereka yang mengajukan lebih dulu.",
  "city.odidi-embassy.displayName": "Odidi · Ruang Penerimaan Diplomatik",
  "journal.interaction-doppel-lab-01.title": "Buku Harian Penugasan yang Tak Kembali",
  "journal.interaction-doppel-lab-01.body": "Buku harian seorang peneliti yang pernah dikirim ke Eternal. Halaman terakhirnya hanya satu baris, \"Pengganti sudah tiba,\" dan kotak tanda tangan di bawahnya masih kosong.",
  "city.department.exchange": "Kantor Tukar",
  "city.department.council": "Dewan",
  "city.doppel-parlor.displayName": "Doppel · Ruang Tamu Lab Riset Pusat",
