  "shopClerk.protia.name": "Protia",
  "shopClerk.haine.name": "Haine",
  "journal.interaction-doppel-01.title": "Papan Koridor Biru",
  "journal.interaction-doppel-01.body": "Papan pengumuman pertama rumah kaca masih memuat kalimat yang meminta agar tubuh yang dipulihkan disambut sebagai tetangga baru, bukan tontonan.",
  "journal.interaction-doppel-02.title": "Salam yang Berulang",
  "bond.torika.0": "Kamu siapa?",
  "bond.torika.1": "Kamu datang lagi.",
  "bond.torika.2": "Kamu boleh di sampingku.",
  "bond.torika.3": "Hari ini kita ngapain?",
  "bond.torika.4": "Aku kenal langkah kakimu.",
  "bond.torika.5": "Tenang rasanya kalau bersama.",
  "bond.torika.6": "Aku akan menjaga punggungmu.",
  "bond.torika.7": "Aku sudah menunggu.",
  "bond.torika.8": "Aku merasa aman kalau kamu datang.",
  "bond.torika.9": "Aku akan ikut denganmu sampai akhir.",
  "bond.torika.10": "Taman kita akan kulindungi sendiri.",
  "bond.rex.0": "Jangan sentuh aku.",
  "bond.rex.1": "Tidak takut, ya?",
  "bond.rex.2": "Sedikit menarik.",
  "bond.rex.3": "Ikut juga di perburuan berikutnya.",
  "bond.rex.4": "Aku sudah hafal aromamu.",
  "bond.rex.5": "Jangan jauh-jauh dariku.",
  "bond.rex.6": "Apa pun yang menyerangmu, akan kugigit.",
  "bond.rex.7": "Hari ini telat lagi.",
  "bond.rex.8": "Aku lebih suka suaramu daripada perintah.",
  "bond.rex.9": "Kamu satu-satunya kawananku.",
  "bond.rex.10": "Aku akan selalu di pihakmu.",
  "bond.spino.0": "…Ada apa?",
  "bond.spino.1": "Aku rindu air.",
  "bond.spino.2": "Diam saja juga tidak apa-apa.",
  "bond.spino.3": "Ceritakan lagi tentang dirimu.",
  "bond.spino.4": "Ombak hari ini tenang.",
  "bond.spino.5": "Aku suka berjalan bersama.",
  "bond.spino.6": "Kalau berbahaya, berlindung di belakangku.",
  "bond.spino.7": "Aku tahu kamu akan datang.",
  "bond.spino.8": "Aku sudah terbiasa dengan kota ini.",
  "bond.spino.9": "Di sisimu adalah airku.",
  "bond.spino.10": "Ayo mengalir ke mana saja bersama.",
  "bond.generic.0": "Masih agak asing.",
  "bond.generic.1": "Hari ini kita bertemu lagi.",
  "bond.generic.2": "Pelan-pelan mulai terbiasa.",
  "bond.generic.3": "Ayo menjalankan misi bersama.",
  "bond.generic.4": "Aku senang kalau kamu datang.",
  "bond.generic.5": "Kamu boleh di sampingku.",
  "bond.generic.6": "Kali ini aku akan membantu lagi.",
  "bond.generic.7": "Aku sudah menunggu.",
  "bond.generic.8": "Kita rekan yang baik.",
  "bond.generic.9": "Aku ingin bersama lama.",
  "bond.generic.10": "Ke depannya aku mengandalkanmu.",
