  "relic.taboa.name": "Taboa",
  "relic.taboa.origin": "Titanoboa",
  "relic.taboa.excavationSite": "Lapisan Paleosen, tambang batu bara Cerrejón, Kolombia",
  "relic.taboa.fossilRecord": "Puluhan ruas tulang belakang ditemukan dalam satu garis bersambung di antara lapisan batu bara tambang terbuka. Panjang tubuh yang diukur dari tulang melampaui ular hidup mana pun, dan panas tropis yang diperlukan untuk menghangatkan tubuh seperti itu diperkirakan sekaligus.",
  "relic.taboa.catalogSummary": "Spesimen besar berbasis Titanoboa dengan ekor dan jubah bersisik yang direstorasi berlebihan.",
  "relic.taboa.unlockRecord": "Catatan Bencana 005. Muncul di sekitar lahan basah tropis. Ia mengenakan tudung berbentuk mulut ular dan menjuntaikan ekor panjang bersisik merah tua, dengan rantai dan label gembok tergantung seperti perhiasan. Ia melilitkan ekornya pada sasaran yang berdiri dekat dan tidak melepaskan apa yang telah dililitnya sampai roboh. Asal-usulnya dan apa yang diincarnya belum dapat dipastikan.",
  "relic.taboa.observation.originYear": "Sekitar 60 juta tahun lalu",
  "relic.taboa.observation.restorationYear": "E.C. 17",
  "relic.taboa.observation.lifeStage": "Dewasa",
  "relic.taboa.observation.height": "1,72 m",
  "relic.taboa.observation.weight": "146 kg",
  "relic.taboa.passive.desc": "Setiap serangan dasar mengenai, Kecepatan Serang naik selama pertarungan ini.",
  "relic.taboa.passive.name": "Tubuh yang Memanas",
  "relic.taboa.ferocity.name": "Meja Sang Pelahap",
  "relic.taboa.basic.name": "Lilit",
  "relic.taboa.ultimate.name": "Pelukan yang Mencekik",
  "relic.taboa.projectName": "ANNIHILATION SIEGE 005",
  "relic.quetzalcoatlus.name": "Koatl",
  "relic.quetzalcoatlus.origin": "Quetzalcoatlus",
  "relic.quetzalcoatlus.excavationSite": "Endapan sungai Kapur Akhir, Big Bend, Texas, AS",
  "relic.quetzalcoatlus.fossilRecord": "Sebaris ruas tulang leher berongga ditemukan tersambung dalam satu garis di lapisan batu lumpur tepi sungai. Dinding tulangnya setipis kertas sehingga diduga berfungsi menjaga tubuh tetap melayang, dan permukaan sedimen yang hanya menyisakan bekas ujung sayap turut dicatat.",
  "relic.quetzalcoatlus.catalogSummary": "Spesimen besar berbasis Quetzalcoatlus dengan leher dan selaput sayap yang direstorasi berlebihan.",
  "relic.quetzalcoatlus.unlockRecord": "Catatan Bencana 006. Muncul di langit di atas tepi sungai. Ia mengenakan jubah hitam yang terbentang seperti sayap dan topi lebar berujung runcing, dengan hiasan berbentuk mata panah berayun pada rantainya. Ia lama memandang dari ketinggian lalu menukik dalam satu serangan, dan satu kepakan sayap menyapu peralatan di dekatnya. Asal-usulnya dan apa yang diincarnya belum dapat dipastikan.",
  "relic.quetzalcoatlus.observation.originYear": "Sekitar 68 juta tahun lalu",
  "relic.quetzalcoatlus.observation.restorationYear": "E.C. 18",
  "relic.quetzalcoatlus.observation.lifeStage": "Dewasa",
  "relic.quetzalcoatlus.observation.height": "2,15 m",
