  "relic.raitia-grass.origin": "Dormouse",
  "relic.raitia-grass.excavationSite": "Sedimen gua karst Slovenia",
  "relic.raitia-grass.fossilRecord": "Puluhan tengkorak spesies yang sama ditemukan dari satu lapisan sedimen gua. Lima di antaranya begitu cocok dalam ukuran dan susunan gigi sehingga digolongkan satu perindukan.",
  "relic.raitia-grass.catalogSummary": "Spesimen berbasis dormouse yang direstorasi dengan gigi seri dan kantong pipi berukuran besar.",
  "relic.raitia-grass.squadNote": "Massa sekali pakai Pemusnahan. Mereka mengalir serentak ke arah yang ditunjuk dan memenuhi lorong, yang di belakang langsung melangkahi tempat yang di depan jatuh.",
  "relic.raitia-grass.researcherTitle": "Periset",
  "relic.raitia-grass.unlockRecord": "Catatan Identifikasi 207. Terkonfirmasi tergabung dalam Pemusnahan. Dari lima sosok berpiama berkerudung bertelinga tikus, yang ini mengenakan simpul hijau; kantong berbentuk keju, sandal bergigi, dan ekor belang berpita di ujungnya menonjol. Saat menemukan makanan, ia memberi sinyal bukan dengan cicitan melainkan bunyi gigi serinya, dan saudari-saudari yang mendengar berkerumun ke tempat yang sama sekaligus. Di bekas gigitannya tercecer tunas segar, dan di setiap jejak kaki sepanjang jalannya biji bertunas hingga meninggalkan jalur hijau. Mengapa ia tak berhenti makan bahkan saat musim hibernasi tiba belum terkonfirmasi.",
  "relic.raitia-grass.observation.originYear": "Sekitar 2 juta tahun lalu",
  "relic.raitia-grass.observation.restorationYear": "E.C. 2",
  "relic.raitia-grass.observation.lifeStage": "Remaja",
  "relic.raitia-grass.observation.height": "0,94 m",
  "relic.raitia-grass.observation.weight": "21 kg",
  "relic.raitia-grass.passive.name": "Hibernasi",
  "relic.raitia-grass.passive.desc": "Sekali per pertarungan, saat HP turun ke separuh atau kurang, memulihkan 3% HP maksimum tiap detik selama 5 detik.",
  "relic.raitia-grass.ferocity.name": "Melahap",
  "relic.raitia-grass.basic.name": "Gigitan Gigi Seri",
  "relic.raitia-grass.ultimate.name": "Tumpahan Kantong Pipi",
  "relic.raitia-grass.projectName": "ANNIHILATION SWARM — Populasi Kekenyangan",
  "relic.raitia-water.name": "Guttia",
  "relic.raitia-water.origin": "Dormouse",
  "relic.raitia-water.excavationSite": "Sedimen gua karst Slovenia",
  "relic.raitia-water.fossilRecord": "Puluhan tengkorak spesies yang sama ditemukan dari satu lapisan sedimen gua. Lima di antaranya begitu cocok dalam ukuran dan susunan gigi sehingga digolongkan satu perindukan.",
  "relic.raitia-water.catalogSummary": "Spesimen berbasis dormouse yang direstorasi dengan gigi seri dan kantong pipi berukuran besar.",
  "relic.raitia-water.squadNote": "Massa sekali pakai Pemusnahan. Mereka mengalir serentak ke arah yang ditunjuk dan memenuhi lorong, yang di belakang langsung melangkahi tempat yang di depan jatuh.",
  "relic.raitia-water.researcherTitle": "Periset",
  "relic.raitia-water.unlockRecord": "Catatan Identifikasi 208. Terkonfirmasi tergabung dalam Pemusnahan. Di antara sosok berpiama berkerudung yang sama, yang ini berekor belang biru dengan bola kapas di ujungnya, tersenyum dengan satu tangan di pinggang dan jari tangan lainnya di sudut bibir. Saat mendengar bunyi gigi seri saudarinya, ia tersenyum dan lari keluar paling dulu, dan begitu dekat ia menggerogoti perlengkapan apa pun yang terjangkau tangan dengan gigi serinya. Jejak kaki basah memanjang di tempat kawanan itu lewat. Apa yang membasahi jejak itu belum terkonfirmasi.",
  "relic.raitia-water.observation.originYear": "Sekitar 2 juta tahun lalu",
  "relic.raitia-water.observation.restorationYear": "E.C. 2",
  "relic.raitia-water.observation.lifeStage": "Remaja",
  "relic.raitia-water.observation.height": "0,94 m",
  "relic.raitia-water.observation.weight": "21 kg",
  "relic.raitia-water.passive.name": "Hibernasi",
  "relic.raitia-water.passive.desc": "Sekali per pertarungan, saat HP turun ke separuh atau kurang, memulihkan 3% HP maksimum tiap detik selama 5 detik.",
  "relic.raitia-water.ferocity.name": "Melahap",
  "relic.raitia-water.basic.name": "Gigitan Gigi Seri",
  "relic.raitia-water.ultimate.name": "Tumpahan Kantong Pipi",
  "relic.raitia-water.projectName": "ANNIHILATION SWARM — Populasi Kekenyangan",
  "relic.raitia-fire.name": "Favia",
  "relic.raitia-fire.origin": "Dormouse",
  "relic.raitia-fire.excavationSite": "Sedimen gua karst Slovenia",
  "relic.raitia-fire.fossilRecord": "Puluhan tengkorak spesies yang sama ditemukan dari satu lapisan sedimen gua. Lima di antaranya begitu cocok dalam ukuran dan susunan gigi sehingga digolongkan satu perindukan.",
  "relic.raitia-fire.catalogSummary": "Spesimen berbasis dormouse yang direstorasi dengan gigi seri dan kantong pipi berukuran besar.",
  "relic.raitia-fire.squadNote": "Massa sekali pakai Pemusnahan. Mereka mengalir serentak ke arah yang ditunjuk dan memenuhi lorong, yang di belakang langsung melangkahi tempat yang di depan jatuh.",
  "relic.raitia-fire.researcherTitle": "Periset",
  "relic.raitia-fire.unlockRecord": "Catatan Identifikasi 209. Terkonfirmasi tergabung dalam Pemusnahan. Di antara sosok berpiama berkerudung yang sama, yang ini berpita kotak-kotak merah muda, berdiri dengan wajah setengah sadar, satu tangan mengucek mata dan tangan lainnya di pinggang. Meski tampak mengantuk, ia tak berhenti makan, dan terus menggerogoti dengan gigi serinya bahkan setelah kantong pipinya penuh. Saat saudari-saudarinya berhamburan, ia mengikuti di belakang sambil mengucek mata. Apakah kantuknya pura-pura atau sungguhan belum terkonfirmasi.",
  "relic.raitia-fire.observation.originYear": "Sekitar 2 juta tahun lalu",
  "relic.raitia-fire.observation.restorationYear": "E.C. 2",
  "relic.raitia-fire.observation.lifeStage": "Remaja",
  "relic.raitia-fire.observation.height": "0,94 m",
  "relic.raitia-fire.observation.weight": "21 kg",
  "relic.raitia-fire.passive.name": "Hibernasi",
  "relic.raitia-fire.passive.desc": "Sekali per pertarungan, saat HP turun ke separuh atau kurang, memulihkan 3% HP maksimum tiap detik selama 5 detik.",
