  "relic.raitia-earth.excavationSite": "Sedimen gua karst Slovenia",
  "relic.raitia-earth.fossilRecord": "Puluhan tengkorak spesies yang sama ditemukan dari satu lapisan sedimen gua. Lima di antaranya begitu cocok dalam ukuran dan susunan gigi sehingga digolongkan satu perindukan.",
  "relic.raitia-earth.catalogSummary": "Spesimen berbasis dormouse yang direstorasi dengan gigi seri dan kantong pipi berukuran besar.",
  "relic.raitia-earth.squadNote": "Massa sekali pakai Pemusnahan. Mereka mengalir serentak ke arah yang ditunjuk dan memenuhi lorong, yang di belakang langsung melangkahi tempat yang di depan jatuh.",
  "relic.raitia-earth.researcherTitle": "Periset",
  "relic.raitia-earth.unlockRecord": "Catatan Identifikasi 210. Terkonfirmasi tergabung dalam Pemusnahan. Di antara sosok berpiama berkerudung yang sama, yang ini menonjol dengan dasar cokelat, simpul kuning, dan rambut kepang, serta membawa gumpalan bulu besar di ujung ekornya. Saat ia berdiri dengan tangan terulur ke depan, para saudarinya mengalir serentak ke arah ujung jarinya, dan di tempat sosok terdepan jatuh, sosok di belakang langsung menginjak melewatinya. Siapa yang menentukan arah ujung jarinya belum terkonfirmasi.",
  "relic.raitia-earth.observation.originYear": "Sekitar 2 juta tahun lalu",
