  "relic.raitia-wind.fossilRecord": "Puluhan tengkorak spesies yang sama ditemukan dari satu lapisan sedimen gua. Lima di antaranya begitu cocok dalam ukuran dan susunan gigi sehingga digolongkan satu perindukan.",
  "relic.raitia-wind.catalogSummary": "Spesimen berbasis dormouse yang direstorasi dengan gigi seri dan kantong pipi berukuran besar.",
  "relic.raitia-wind.squadNote": "Massa sekali pakai Pemusnahan. Mereka mengalir serentak ke arah yang ditunjuk dan memenuhi lorong, yang di belakang langsung melangkahi tempat yang di depan jatuh.",
  "relic.raitia-wind.researcherTitle": "Periset",
  "relic.raitia-wind.unlockRecord": "Catatan identifikasi 211. Dipastikan berafiliasi dengan Pemusnahan. Ia individu berpita warna mint di antara saudari-saudarinya yang mengenakan piama berkerudung yang sama, berdiri dengan tangan bersedekap dan mulut terkatup rapat. Ia baru mengikuti dengan setengah hati setelah saudari-saudarinya berduyun-duyun menuju makanan, tetapi begitu tiba, dialah yang paling lama menggerakkan gigi serinya. Tak pernah sekali pun teramati ia memberi tanda dengan bunyi gigi serinya.",
